    "id": "comic-speech-theme",
    "filename": "comic-speech-theme.css",
    "css": "/* Visual Settings: uses CSS custom properties for live customization */\n/**\n * Theme Name: Comic Speech\n * Description: Messages pop in speech balloons with a tail to the avatar, thick ink outlines and halftone\n * Tags: comic, pop-art, speech-bubble, bold, playful\n * Author: All-Chat Team\n * Version: 1.0.0\n * Updated: 2026-07-08\n */\n\n@import url('https://fonts.googleapis.com/css2?family=Bangers&family=Poppins:wght@400;500;600&display=swap');\n\n/* Message text is theme-controlled; usernames keep their viewer-defined color. */\n:root {\n  --chat-message-color: #1a1a1a;\n  --chat-timestamp-color: #7a7a7a;\n}\n\nbody {\n  background: transparent !important;\n  font-family: 'Poppins', sans-serif !important;\n}\n\n.space-y-3 {\n  gap: var(--chat-message-gap, 14px) !important;\n}\n\n/* The message container is invisible — the balloon is drawn on the content */\n.chat-message {\n  background: transparent !important;\n  border: none !important;\n  box-shadow: none !important;\n  padding: 0 !important;\n  overflow: visible !important;\n}\n\n.chat-message .flex.items-start.gap-3 {\n  align-items: center !important;\n  gap: 16px !important;\n}\n\n/* Avatar — inked circle */\n.flex-shrink-0 img {\n  border-radius: 50% !important;\n  border: 3px solid #000000 !important;\n  box-shadow: 3px 3px 0 rgba(0, 0, 0, 0.25) !important;\n}\n\n/* Content → the speech balloon */\n.chat-message .min-w-0.flex-1 {\n  position: relative !important;\n  background-color: #ffffff !important;\n  background-image: radial-gradient(rgba(0, 0, 0, 0.06) 1.2px, transparent 1.2px) !important;\n  background-size: 9px 9px !important;\n  border: 3px solid #000000 !important;\n  border-radius: 16px !important;\n  padding: 10px 14px !important;\n  box-shadow: 4px 4px 0 #000000 !important;\n}\n\n/* Balloon tail pointing at the avatar (outline + fill) */\n.chat-message .min-w-0.flex-1::before {\n  content: '' !important;\n  position: absolute !important;\n  left: -17px !important;\n  top: 16px !important;\n  border: 9px solid transparent !important;\n  border-right-color: #000000 !important;\n}\n.chat-message .min-w-0.flex-1::after {\n  content: '' !important;\n  position: absolute !important;\n  left: -11px !important;\n  top: 18px !important;\n  border: 7px solid transparent !important;\n  border-right-color: #ffffff !important;\n}\n\n/* Platform badge — little ink tab */\n.platform-badge-text {\n  background: #000000 !important;\n  color: #ffffff !important;\n  border-radius: 4px !important;\n  padding: 1px 7px !important;\n  font-family: 'Bangers', cursive !important;\n  letter-spacing: 0.08em !important;\n}\n\n/* Username — comic caps, viewer color kept, ink outline */\n.chat-username {\n  font-family: 'Bangers', cursive !important;\n  font-weight: 400 !important;\n  font-size: 1.2em !important;\n  letter-spacing: 0.03em !important;\n  paint-order: stroke fill !important;\n  -webkit-text-stroke: 1px #000000 !important;\n}\n\n/* Message text — dark ink on the balloon */\n.chat-message .break-words.text-white {\n  color: #1a1a1a !important;\n  font-family: 'Poppins', sans-serif !important;\n  font-size: var(--chat-font-size, 15px) !important;\n  font-weight: 500 !important;\n  line-height: var(--chat-line-height, 1.45) !important;\n}\n\n.chat-message .break-words img {\n  max-height: calc(24px * var(--chat-emote-scale, 1)) !important;\n  vertical-align: middle !important;\n}\n\n.text-slate-500 {\n  color: #8a8a8a !important;\n  font-size: var(--chat-timestamp-font-size, 11px) !important;\n}\n",
