    "css": "/* Visual Settings: uses CSS custom properties for live customization */\n/**\n * Theme Name: Cyberpunk 2077 Theme\n * Description: High-tech dystopian cyberpunk aesthetic with glitch effects and neon yellow accents\n * Tags: cyberpunk, neon, futuristic, yellow\n * Author: All-Chat Team\n * Version: 1.0.0\n * Updated: 2026-01-08\n */\n\n/* ============================================================\n   CYBERPUNK 2077 THEME for All-Chat Overlay\n   ============================================================\n\n   A dystopian cyberpunk design featuring:\n   - High-contrast yellow/black color scheme\n   - Glitch-style text effects\n   - Angular, tech-inspired shapes\n   - Scan line effects\n   - Digital/grid background patterns\n\n   ============================================================ */\n\n@import url('https://fonts.googleapis.com/css2?family=Rajdhani:wght@500;600;700&family=Share+Tech+Mono&display=swap');\n\n/* ============================================================\n   CORE STYLES\n   ============================================================ */\n\nbody {\n  background: transparent !important;\n  font-family: var(--chat-font-family, 'Rajdhani', sans-serif) !important;\n  -webkit-font-smoothing: antialiased !important;\n}\n\n.min-h-screen {\n  background: var(--chat-overlay-bg-color, transparent) !important;\n  padding: var(--chat-overlay-padding, 16px) !important;\n}\n\n.space-y-3 {\n  gap: var(--chat-message-gap, 16px) !important;\n}\n\n/* ============================================================\n   MESSAGE CONTAINER - CYBERPUNK PANEL\n   ============================================================ */\n\n.space-y-3 > div {\n  background: var(--chat-bubble-bg-color, linear-gradient(135deg, rgba(0, 0, 0, 0.95) 0%, rgba(20, 20, 0, 0.9) 100%)) !important;\n  border: var(--chat-bubble-border-width, 2px) solid #ffed4e !important;\n  border-left: 6px solid #ffed4e !important;\n  border-radius: var(--chat-bubble-border-radius, 0) !important;\n  padding: var(--chat-bubble-padding, 1rem) !important;\n  box-shadow:\n    0 0 20px rgba(255, 237, 78, 0.3),\n    inset 0 1px 0 rgba(255, 237, 78, 0.2),\n    0 4px 8px rgba(0, 0, 0, 0.8) !important;\n  position: relative !important;\n  clip-path: polygon(0 0, 100% 0, 100% calc(100% - 8px), calc(100% - 8px) 100%, 0 100%) !important;\n}\n\n/* Scan line effect */\n.space-y-3 > div::before {\n  content: '' !important;\n  position: absolute !important;\n  top: 0 !important;\n  left: 0 !important;\n  right: 0 !important;\n  bottom: 0 !important;\n  background: repeating-linear-gradient(\n    0deg,\n    rgba(255, 237, 78, 0.03) 0px,\n    transparent 1px,\n    transparent 2px,\n    rgba(255, 237, 78, 0.03) 3px\n  ) !important;\n  pointer-events: none !important;\n  z-index: 1 !important;\n}\n\n/* Corner accent */\n.space-y-3 > div::after {\n  content: '' !important;\n  position: absolute !important;\n  bottom: 0 !important;\n  right: 0 !important;\n  width: 12px !important;\n  height: 12px !important;\n  border-right: 2px solid #ffed4e !important;\n  border-bottom: 2px solid #ffed4e !important;\n  clip-path: polygon(100% 0, 100% 100%, 0 100%) !important;\n}\n\n/* ============================================================\n   PLATFORM INDICATOR - CYBER TAG\n   ============================================================ */\n\n.text-xs.font-semibold.uppercase {\n  background: #ffed4e !important;\n  color: #000000 !important;\n  padding: 0.2rem 0.8rem !important;\n  border-radius: 0 !important;\n  letter-spacing: 0.2em !important;\n  font-weight: 700 !important;\n  font-size: 10px !important;\n  font-family: 'Share Tech Mono', monospace !important;\n  box-shadow: 0 0 10px rgba(255, 237, 78, 0.6), inset 0 -2px 0 rgba(0, 0, 0, 0.3) !important;\n  text-shadow: none !important;\n  clip-path: polygon(0 0, calc(100% - 6px) 0, 100% 50%, calc(100% - 6px) 100%, 0 100%) !important;\n}\n\n/* ============================================================\n   USERNAME - GLITCH STYLE\n   ============================================================ */\n\n.font-semibold.text-sm {\n  font-family: var(--chat-username-font-family, 'Rajdhani', sans-serif) !important;\n  font-size: var(--chat-username-font-size, 18px) !important;\n  font-weight: var(--chat-username-font-weight, 700) !important;\n  text-transform: uppercase !important;\n  letter-spacing: var(--chat-letter-spacing, 0.05em) !important;\n  text-shadow:\n    2px 0 0 rgba(255, 0, 255, 0.4),\n    -2px 0 0 rgba(0, 255, 255, 0.4),\n    0 0 10px rgba(255, 237, 78, 0.5) !important;\n  filter: contrast(1.2) !important;\n  position: relative !important;\n  z-index: 2 !important;\n}\n\n/* ============================================================\n   BADGES - CYBER STYLE\n   ============================================================ */\n\n.flex.gap-1 {\n  gap: 6px !important;\n  filter: drop-shadow(0 0 4px rgba(255, 237, 78, 0.6)) !important;\n  position: relative !important;\n  z-index: 2 !important;\n}\n\n.flex.gap-1 img {\n  width: 20px !important;\n  height: 20px !important;\n  border: 1px solid #ffed4e !important;\n  border-radius: 0 !important;\n  padding: 2px !important;\n  background: rgba(0, 0, 0, 0.8) !important;\n}\n\n/* ============================================================\n   AVATAR - ANGULAR STYLE\n   ============================================================ */\n\n.flex-shrink-0 img {\n  border: 2px solid #ffed4e !important;\n  border-radius: 0 !important;\n  box-shadow: 0 0 15px rgba(255, 237, 78, 0.4) !important;\n  clip-path: polygon(0 0, calc(100% - 8px) 0, 100% 8px, 100% 100%, 8px 100%, 0 calc(100% - 8px)) !important;\n}\n\n/* ============================================================\n   MESSAGE TEXT - DIGITAL READOUT\n   ============================================================ */\n\n.text-white.break-words {\n  font-family: var(--chat-font-family, 'Rajdhani', sans-serif) !important;\n  font-size: var(--chat-font-size, 17px) !important;\n  font-weight: var(--chat-font-weight, 500) !important;\n  color: var(--chat-message-color, #e0e0e0) !important;\n  line-height: var(--chat-line-height, 1.6) !important;\n  text-shadow: 0 0 5px rgba(255, 237, 78, 0.3) !important;\n  position: relative !important;\n  z-index: 2 !important;\n}\n\n.text-white.break-words img {\n  max-height: calc(28px * var(--chat-emote-scale, 1)) !important;\n  filter: drop-shadow(0 0 6px rgba(255, 237, 78, 0.3)) !important;\n}\n\n/* ============================================================\n   TIMESTAMP - TECH STYLE\n   ============================================================ */\n\n.text-xs.text-gray-500 {\n  font-family: var(--chat-timestamp-font-family, 'Share Tech Mono', monospace) !important;\n  font-size: var(--chat-timestamp-font-size, 10px) !important;\n  color: var(--chat-timestamp-color, #ffed4e) !important;\n  text-shadow: 0 0 5px rgba(255, 237, 78, 0.4) !important;\n  letter-spacing: 0.1em !important;\n}\n\n/* ============================================================\n   ANIMATIONS\n   ============================================================ */\n\n@keyframes glitchIn {\n  0% {\n    opacity: 0;\n    transform: translateX(-20px);\n    filter: blur(2px);\n  }\n  50% {\n    transform: translateX(5px);\n  }\n  100% {\n    opacity: 1;\n    transform: translateX(0);\n    filter: blur(0);\n  }\n}\n\n.space-y-3 > div {\n  animation: glitchIn 0.3s ease-out !important;\n}\n\n/* ============================================================\n   END OF CYBERPUNK THEME\n   ============================================================ */\n",
